INSERT INTO public.rating (id, created_at, name, rating, message, image, slug, user_id, type) VALUES (24, '2026-09-24 17:56:24.864271+00', 'Rahma Nasrallah', 5, 'تجربة ممتازه من البداية للنهاية واهتمام بالتفاصيل على أعلى مستوى واكتر من ماكنت متوقعه شكرا ع الالتزام والذوق الراقي وارشحه لاي حد بثقة كامله ', null, 'akramahmed5060', '01ba7458-4e02-4b90-920d-e32b1dba3b57', 'engineer'), (25, '2026-09-29 10:46:51.914006+00', 'ZEIN', 5, 'تم التسليم في الموعد المحدد بافضل جودة', null, 'musafwat195', '7d15acdf-1419-47ad-aebe-30317465df6e', 'engineer'), (33, '2026-09-30 11:31:55.95899+00', 'Ahmed walid', 5, 'شركة محترمه و سعر مناسب جدا و تسليم في الموعد بشكركم جدا و ان شاء الله هتعامل معاكم دايما
من تقدم لتقدم بإذن الله ', null, 'valleyholding121', 'c1801d02-f71f-44ab-b5de-c2a831ff7650', 'office'), (48, '2026-10-07 08:00:20.26491+00', 'Hala Talaat', 5, 'مهندس بروفيشنال وكرييتيف محترم و زوق وشغله ممتاز ودؤوب ومواعيده مظبوطة ', null, 'haithammohamed400', 'c4138cab-053a-4c57-a534-cf28d16f14a2', 'engineer'), (52, '2026-10-25 09:47:40.464517+00', 'Basem Ali', 5, 'شكرا يا بشمهندسة على الالتزام بالمواعيد و دقة التنفيذ ', null, 'nourhanhussein', '9213ce39-4960-4d7b-a234-30996a396751', 'engineer'), (62, '2026-10-26 18:59:39.39534+00', 'AKRAM Ahmed AHMED', 5, '"منصة ''تعمير'' خطوة ممتازة ونقلة نوعية لخدمة قطاع الهندسة والمقاولات في مصر. كمشترك في المنصة، أعجبني جداً تنظيم الموقع وسهولة إنشاء الملف الشخصي وعرض خدماتنا المعمارية بشكل احترافي ومنظم يسهل على العميل الوصول إلينا. الفكرة واعدة جداً وتلبي حاجة حقيقية في السوق. كل الدعم للقائمين على المنصة، وفي انتظار انطلاق الحملات التسويقية القوية لتكتمل الرؤية وتصبح المنصة الوجهة الأولى لكل مهندس وعميل في مصر. بالتوفيق دائماً!"', 'https://res.cloudinary.com/drk3bhviw/image/upload/v1790154785/profiles/fq9grmty6pve6sobbhuc.webp', 't3meer', '4bfe5f58-c85c-4c8b-9fdd-f9c672664432', 'engineer');